edit('scripts/presentation/world_volume.gd','func tick_visual() -> void:\n','func tick_visual() -> void:\n\tif kind == "wall":\n\t\tvisible = not world.wall_is_roofed(wall_index) and profile.get("render_enabled",true)\n\telif kind == "fixture":\n\t\tvar fixture: Dictionary = world.fixtures[wall_index]\n\t\tvar inner := not world.is_under_roof(fixture.rect.get_center())\n\t\tvar shell_part := world.roofed_cells.any(func(cell): return cell.rect.grow(20).has_point(fixture.rect.get_center()))\n\t\tvisible = (not fixture.get("hidden",false) or inner and shell_part) and (inner or fixture.has("access_id"))\n')
